// Title: Ensuring a TIFF exported with Aspose.Cells in C# stays within a predefined size limit
// Common Searches: C# Aspose.Cells how to limit exported TIFF file size to 2 MB | check size of TIFF generated by SheetRender.ToImage in .NET | delete oversized TIFF after rendering with Aspose.Cells | validate image file length after Aspose.Cells TIFF export | prevent Aspose.Cells from creating TIFF larger than a set limit
// Tags: Aspose.Cells TIFF size check | C# enforce TIFF max size | SheetRender ToImage size verification | remove large TIFF Aspose | image export size limit .NET

using System;
using System.IO;
using Aspose.Cells;
using Aspose.Cells.Rendering;

// Creates a TIFF from a workbook using Aspose.Cells, then verifies the file size against a 2 MB threshold and removes the file if it exceeds the limit.
class Program
{
    static void Main()
    {
        try
        {
            // Maximum allowed TIFF size (2 MB)
            const long MaxFileSize = 2 * 1024 * 1024;

            // Create a workbook and add sample data
            Workbook workbook = new Workbook();
            Worksheet sheet = workbook.Worksheets[0];
            sheet.Cells["A1"].PutValue("Sample data for TIFF export");
            sheet.Cells["A2"].PutValue(DateTime.Now);
            sheet.Cells["A3"].PutValue(12345);

            // Set image export options for TIFF
            ImageOrPrintOptions imgOptions = new ImageOrPrintOptions
            {
                OnePagePerSheet = true,
                HorizontalResolution = 150,
                VerticalResolution = 150
                // ImageFormat is inferred from the output file extension (TIFF)
            };

            // Render the worksheet to a TIFF file
            SheetRender renderer = new SheetRender(sheet, imgOptions);
            string outputPath = "output.tiff";

            // Ensure any existing file is removed before rendering
            if (File.Exists(outputPath))
            {
                File.Delete(outputPath);
            }

            // Render directly to file (format based on extension)
            renderer.ToImage(0, outputPath);

            // Verify generated size does not exceed the limit
            FileInfo fileInfo = new FileInfo(outputPath);
            if (fileInfo.Length > MaxFileSize)
            {
                Console.WriteLine($"Generated TIFF size ({fileInfo.Length} bytes) exceeds the maximum allowed ({MaxFileSize} bytes).");
                // Optionally delete the oversized file
                File.Delete(outputPath);
                return;
            }

            Console.WriteLine($"TIFF generated successfully. Size: {fileInfo.Length} bytes. Saved to '{outputPath}'.");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
